<style>
/* Hero responsive layout — @media required, no SGDS responsive utility classes exist */

/* Default (mobile-first): image below text */
.image-container {
  width: 100%;
  max-width: none;
  margin: 40px auto 0;
}

.image-container svg.landing-hero-art {
  display: block;
  width: 100%;
  height: auto;
  margin: 0 auto;
}

.hero-title {
  font-size: 3.5rem;
  letter-spacing: -0.05em;
}

/* Tablet (768px-1279px): side by side with a smaller illustration than desktop */
@media screen and (min-width: 768px) and (max-width: 1279px) {
  .hero-root {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: clamp(20px, 3vw, 40px);
  }

  .hero-text {
    flex: 1 1 0;
    min-width: 0;
    max-width: none;
  }

  .image-container {
    flex: 0 0 clamp(320px, 42vw, 560px);
    width: clamp(320px, 42vw, 560px);
    max-width: clamp(320px, 42vw, 560px);
    margin: 0;
    align-self: flex-start;
  }
}

@media screen and (min-width: 768px) {
  .hero-title {
    font-size: 4rem;
  }
}

/* Desktop (≥1280px): restore the original hero composition */
@media screen and (min-width: 1280px) {
  .hero-root {
    display: block;
    min-height: 0;
  }

  .hero-text {
    width: auto;
    max-width: 640px;
  }

  .image-container {
    position: absolute;
    top: 0;
    right: 0;
    flex: none;
    width: auto;
    max-width: none;
    margin: 0;
  }

  .image-container svg.landing-hero-art {
    width: 756px;
    height: 744px;
  }

  .hero-title {
    font-size: 5rem;
  }
}

@media screen and (min-width: 1280px) and (max-width: 1439px) {
  .hero-text {
    max-width: 540px;
  }

  .image-container svg.landing-hero-art {
    width: 700px;
    height: auto;
  }
}

/* Local SVG colour bridge for the dark hero semicircle. It uses the SGDS darkest token in day mode and lifts one step in night mode. */
.landing-hero-art {
  --landing-hero-dark-shape: var(--sgds-gray-1100);
}

/* Right purple semicircle — 600 in day, 700 in night (intentionally inverted from the default bg token) */
.landing-hero-art {
  --landing-hero-primary-shape: var(--sgds-product-primary-600);
}

.sgds-night-theme .landing-hero-art {
  --landing-hero-primary-shape: var(--sgds-product-primary-700);
}

.landing-hero-primary-shape {
  fill: var(--landing-hero-primary-shape);
}

.sgds-night-theme .landing-hero-art {
  --landing-hero-dark-shape: var(--sgds-gray-900);
}

/* Apply the same dark-shape token to the black-background floating elements above the right purple semicircle */
.landing-hero-art .black-tile > rect,
.landing-hero-art .black-cube > circle,
.landing-hero-art .black-disk > circle {
  fill: var(--landing-hero-dark-shape);
}

/* Hero title text colour — matches the dark semicircle token intentionally */
.landing-hero-title {
  color: var(--sgds-gray-1100);
}

.sgds-night-theme .landing-hero-title {
  color: var(--sgds-gray-900);
}
</style>
